import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.Bbwa0s72.js";const h=JSON.parse('{"title":"0005 — Current Form Packages use content-addressed publication locators","description":"","frontmatter":{},"headers":[],"relativePath":"spec/decisions/0005-current-form-packages-use-content-addressed-locators.md","filePath":"spec/decisions/0005-current-form-packages-use-content-addressed-locators.md"}'),s={name:"spec/decisions/0005-current-form-packages-use-content-addressed-locators.md"};function n(o,e,c,l,d,p){return t(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="_0005-—-current-form-packages-use-content-addressed-publication-locators" tabindex="-1">0005 — Current Form Packages use content-addressed publication locators <a class="header-anchor" href="#_0005-—-current-form-packages-use-content-addressed-publication-locators" aria-label="Permalink to &quot;0005 — Current Form Packages use content-addressed publication locators&quot;">​</a></h1><ul><li>Status: superseded for current v1alpha2 Forms by <a href="./0006-v1alpha2-restarts-form-lines.html">0006</a>; retained for immutable content-addressed packages carrying v1alpha1 Legacy FormRefs</li><li>Date: 2026-08-04</li><li>Owners: Takoform maintainers</li><li>Supersedes: the current-package <code>packageVersion</code> decision in <a href="./0001-provider-v1-keeps-form-versions-independent.html">0001</a></li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>A published Form already has a semantic compatibility identity in its exact <code>FormRef</code>, while a Form Package already has a byte identity in <code>packageDigest</code>. The v1alpha1 package format added a second SemVer <code>packageVersion</code> and reused it in the source directory, Git tag, release asset names, and manifests. In practice it duplicated the Form version and made package transport look like another maturity clock. It also allowed fixtures or explanatory payload changes to compete with the Form contract&#39;s SemVer.</p><p>The 71 published v1alpha1 release identities, including their paths, tags, manifests, signatures, and package indexes, are immutable Legacy evidence and cannot be renamed or rewritten.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>New current packages use <code>packages.forms.takoform.com/v1alpha2</code>. The index has no <code>packageVersion</code>; its exact <code>packageDigest</code> is the only Package Artifact identity. A current publication locator is derived mechanically as:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>artifact ID  = sha256-&lt;64 lowercase hex&gt;</span></span>
<span class="line"><span>source path  = forms/releases/&lt;release-id&gt;/&lt;artifact-id&gt;</span></span>
<span class="line"><span>Git tag      = forms/&lt;release-id&gt;/&lt;artifact-id&gt;</span></span></code></pre></div><p><code>FormRef.definitionVersion</code> remains the Form contract&#39;s SemVer and retains its compatibility meaning. The provider version remains independent. Publication, Form maturity, Host Support, activation, and commercial availability remain separate facts.</p><p>The verifier accepts both profiles through one package-verification interface: v1alpha1 is a read/recovery compatibility profile with its exact SemVer locator; v1alpha2 is the only profile accepted for new current lifecycle records and publications. A caller must not infer a profile from directory names or labels after parsing the signed canonical index.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>changing any indexed package payload produces a new Package Digest and a new immutable locator without pretending the Form contract changed;</li><li>changing Form semantics still requires a new exact FormRef under the Form compatibility policy;</li><li>the current lifecycle and release verifier can derive path, tag, and asset identity from one verified package result;</li><li>all existing v1alpha1 readers, tags, source paths, release assets, signatures, revocations, and recovery evidence remain valid and unchanged;</li><li>hosts add v1alpha2 support before a real current package is published; there is no flag day and no reinterpretation of persisted v1alpha1 records.</li></ul><h2 id="rejected-alternatives" tabindex="-1">Rejected alternatives <a class="header-anchor" href="#rejected-alternatives" aria-label="Permalink to &quot;Rejected alternatives&quot;">​</a></h2><ul><li><strong>Keep <code>packageVersion</code> but document that it is meaningless.</strong> Rejected because a required public SemVer is inevitably treated as a compatibility or maturity signal and still creates two clocks.</li><li><strong>Reuse <code>FormRef.definitionVersion</code> as the package locator.</strong> Rejected because more than one exact package artifact can carry the same Form Definition while improving fixtures, evidence, or non-semantic documentation.</li><li><strong>Put only a shortened digest in the locator.</strong> Rejected because collision handling would introduce another registry rule; the full SHA-256 is already the canonical identity.</li></ul>`,14)])])}const m=a(s,[["render",n]]);export{h as __pageData,m as default};
